{"file_path":"src/limits.js","content":"/**
 * The two policy kinds a route can enforce: token buckets and sliding
 * windows. Each keeps one independent state per key, created lazily the
 * first time that key reaches the policy.
 */

/** A token bucket: capacity tokens, refilling `refill` per `per` ticks. */
export class BucketPolicy {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  /**
   * Advance the key's bucket to `tick`. Tokens are tracked as a numerator
   * scaled by `per` (so `numerator / per` is the actual token count),
   * which lets partial-period refills accumulate as an exact fraction
   * instead of a rounded decimal.
   */
  advance(key, tick) {
    const full = this.capacity * this.per
    let state = this.states.get(key)
    if (!state) {
      state = { last: tick, numerator: full }
      this.states.set(key, state)
      return
    }
    const elapsed = tick - state.last
    if (elapsed > 0n) {
      let numerator = state.numerator + this.refill * elapsed
      if (numerator > full) numerator = full
      state.numerator = numerator
      state.last = tick
    }
  }

  allow(key) {
    return this.states.get(key).numerator >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.numerator -= this.per
  }
}

/** A sliding window: allows up to `limit` requests inside the last `span` ticks. */
export class WindowPolicy {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  /** Advance the key's window to `tick`, forgetting ticks that fell out of range. */
  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = []
      this.states.set(key, state)
    }
    const threshold = tick - this.span
    while (state.length > 0 && state[0] <= threshold) state.shift()
  }

  allow(key) {
    const state = this.states.get(key)
    return BigInt(state.length) < this.limit
  }

  record(key, tick) {
    this.states.get(key).push(tick)
  }
}
"}

