{"file_path":"src/parser.js","content":"/**
 * Parses a limiter file into its declarations and its event log,
 * enforcing every structural rule the specification states. On the
 * first problem it throws a {@link ParseError} carrying the line number
 * and the message text the CLI writes to standard error.
 */

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

/** Thrown for the first malformed or out-of-order line; carries the 1-based line number. */
export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

function fail(line, message) {
  throw new ParseError(line, message)
}

function parseField(token, field, least, line) {
  if (!INT_RE.test(token)) fail(line, `${field} must be an integer of at least ${least}`)
  const value = BigInt(token)
  if (value < least) fail(line, `${field} must be an integer of at least ${least}`)
  return value
}

/**
 * Parse the limiter file text into policy declarations, routes and the
 * event log. Throws {@link ParseError} on the first invalid or
 * out-of-order line.
 */
export function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routesByPrefix = new Map()
  const routes = []
  const events = []
  let eventsSeen = false
  let lastTick = null

  lines.forEach((raw, index) => {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]
    const rest = tokens.slice(1)

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (eventsSeen) fail(line, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (rest.length !== 4) fail(line, 'expected bucket <name> <capacity> <refill> <per>')
      const [name, capacityTok, refillTok, perTok] = rest
      if (!NAME_RE.test(name)) fail(line, `invalid policy name ${name}`)
      const capacity = parseField(capacityTok, 'capacity', 1n, line)
      const refill = parseField(refillTok, 'refill', 0n, line)
      const per = parseField(perTok, 'per', 1n, line)
      if (policies.has(name)) fail(line, `policy ${name} is declared twice`)
      policies.set(name, { kind: 'bucket', capacity, refill, per })
    } else if (directive === 'window') {
      if (rest.length !== 3) fail(line, 'expected window <name> <limit> <span>')
      const [name, limitTok, spanTok] = rest
      if (!NAME_RE.test(name)) fail(line, `invalid policy name ${name}`)
      const limit = parseField(limitTok, 'limit', 0n, line)
      const span = parseField(spanTok, 'span', 1n, line)
      if (policies.has(name)) fail(line, `policy ${name} is declared twice`)
      policies.set(name, { kind: 'window', limit, span })
    } else if (directive === 'route') {
      if (rest.length < 2) fail(line, 'expected route <prefix> <policy>...')
      const [prefix, ...policyNames] = rest
      if (!NAME_RE.test(prefix)) fail(line, `invalid route prefix ${prefix}`)
      if (routesByPrefix.has(prefix)) fail(line, `prefix ${prefix} is routed twice`)
      for (const name of policyNames) {
        if (!policies.has(name)) fail(line, `unknown policy ${name}`)
      }
      const route = { prefix, policies: policyNames }
      routesByPrefix.set(prefix, route)
      routes.push(route)
    } else if (directive === 'event') {
      if (rest.length !== 2) fail(line, 'expected event <tick> <key>')
      const [tickTok, key] = rest
      const tick = parseField(tickTok, 'tick', 0n, line)
      if (!NAME_RE.test(key)) fail(line, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) fail(line, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      eventsSeen = true
      events.push({ tick, key, line })
    } else {
      fail(line, `unknown directive ${directive}`)
    }
  })

  return { policies, routes, events }
}
"}

