import { BucketPolicy, WindowPolicy } from './limits.js'

function buildPolicyInstances(policies) {
  const instances = new Map()
  for (const [name, def] of policies) {
    instances.set(
      name,
      def.kind === 'bucket'
        ? new BucketPolicy(def.capacity, def.refill, def.per)
        : new WindowPolicy(def.limit, def.span),
    )
  }
  return instances
}

/** Find the route whose prefix is longest among those that match `key`, or null. */
function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) best = route
    }
  }
  return best
}

/**
 * Run every event through its route's policies in order. Returns the
 * verdicts in log order plus the per-key and total allow/deny tallies.
 */
export function runEvents({ policies, routes, events }) {
  const instances = buildPolicyInstances(policies)
  const verdicts = []
  const perKey = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  for (const { tick, key } of events) {
    const route = findRoute(routes, key)
    const policyNames = route ? route.policies : []
    const policyObjs = policyNames.map((name) => instances.get(name))

    for (const policy of policyObjs) policy.advance(key, tick)

    let denyName = null
    for (let i = 0; i < policyObjs.length; i++) {
      if (!policyObjs[i].allow(key)) {
        denyName = policyNames[i]
        break
      }
    }

    if (denyName === null) {
      for (const policy of policyObjs) policy.record(key, tick)
    }

    let tally = perKey.get(key)
    if (!tally) {
      tally = { allowed: 0, denied: 0 }
      perKey.set(key, tally)
    }
    if (denyName === null) {
      tally.allowed++
      totalAllowed++
    } else {
      tally.denied++
      totalDenied++
    }

    verdicts.push({ tick, key, deny: denyName })
  }

  return { verdicts, perKey, totalAllowed, totalDenied }
}
"}

