{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parseInput, ParseError } from './parser.js'
import { runEvents } from './engine.js'

function usageError() {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const mode = process.argv[2]
if (mode !== 'replay' && mode !== 'summary') usageError()

const input = readFileSync(0, 'utf8')

let parsed
try {
  parsed = parseInput(input)
} catch (error) {
  if (error instanceof ParseError) {
    process.stderr.write(`error: line ${error.line}: ${error.message}\n`)
    process.exit(2)
  }
  throw error
}

const { verdicts, perKey, totalAllowed, totalDenied } = runEvents(parsed)

const lines = []
if (mode === 'replay') {
  for (const { tick, key, deny } of verdicts) {
    lines.push(deny === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${deny}`)
  }
} else {
  const keys = [...perKey.keys()].sort()
  for (const key of keys) {
    const { allowed, denied } = perKey.get(key)
    lines.push(`${key} allowed=${allowed} denied=${denied}`)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
}

process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
"}

